.darma-loader-tw-card-shimmer { position: relative; overflow: hidden; display: flex; flex-direction: column; justify-content: flex-end; gap: calc(var(--loader-size, 180px) * .05); width: var(--loader-size, 180px); height: calc(var(--loader-size, 180px) * .6); padding: calc(var(--loader-size, 180px) * .07); border-radius: calc(var(--loader-size, 180px) * .08); background: color-mix(in srgb, var(--loader-color, #94a3b8) 14%, transparent); box-sizing: border-box; }
.darma-loader-tw-card-shimmer .darma-loader-tw-card-shimmer__row { height: calc(var(--loader-size, 180px) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #94a3b8) 32%, transparent); }
.darma-loader-tw-card-shimmer .darma-loader-tw-card-shimmer__row:last-child { width: 55%; }
.darma-loader-tw-card-shimmer .darma-loader-tw-card-shimmer__glow { position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: linear-gradient(115deg, transparent 30%, color-mix(in srgb, var(--loader-color, #94a3b8) 45%, transparent) 50%, transparent 70%); animation: darma-loader-tw-card-shimmer-twSweep calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
@keyframes darma-loader-tw-card-shimmer-twSweep { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }

